"""Access certificate for acknowledged deliveries."""
import json

from .authority import AuthorityState, OutcomeMismatch
from .timeline import histories

FIELDS = ('receipt', 'copy', 'lineage', 'record', 'captured_owner', 'captured_version',
          'credential', 'ancestry', 'audience')


class CertificateError(Exception):
    """The batch cannot be certified."""


def _step(state, event):
    successor = state.clone()
    try:
        successor.apply(event)
    except OutcomeMismatch:
        return None
    return successor


def build_certificate(batch):
    """Certify only what holds in every history consistent with the batch evidence."""
    problems = {}
    variants = {}
    consistent = False
    for state in histories(batch, AuthorityState(batch['records'], batch['credentials']), _step):
        consistent = True
        for receipt, entry in state.deliveries.items():
            if entry['reason']:
                problems.setdefault(receipt, set()).add(entry['reason'])
            variants.setdefault(receipt, set()).add(json.dumps({k: entry[k] for k in FIELDS}, sort_keys=True))
    if not consistent:
        raise CertificateError('no ordering of the batch events reproduces every recorded outcome')
    errors = ['%s: %s in some ordering consistent with the evidence' % (receipt, '; '.join(sorted(reasons)))
              for receipt, reasons in sorted(problems.items())]
    errors += ['%s: captured provenance is not determined by the evidence (%s)' % (receipt, ' | '.join(sorted(seen)))
               for receipt, seen in sorted(variants.items()) if len(seen) > 1]
    if errors:
        raise CertificateError('; '.join(errors))
    deliveries = [json.loads(next(iter(variants[receipt]))) for receipt in sorted(variants)]
    return {'batch': batch['batch'], 'customer': batch['customer'],
            'deliveries': [{k: d[k] for k in FIELDS} for d in deliveries]}

"""Delivery timeline assembly from the service exports.

Service clocks are independent, so `logged_at` only orders events within one
export. Across services the order is a partial order built from the recorded
evidence; the possible histories are its linear extensions that also reproduce
every recorded operation outcome.
"""
from .batch import events


def precedence(batch):
    """Map each event ID to the IDs that must precede it."""
    flat = events(batch)
    before = {event['id']: set() for event in flat}
    for export in batch['exports']:
        ids = [event['id'] for event in export['events']]
        for earlier, later in zip(ids, ids[1:]):
            before[later].add(earlier)
    for attestation in batch['ordering']:
        before[attestation['later']].add(attestation['earlier'])
    for event in flat:
        if event['kind'] == 'copy' and event['source']['kind'] == 'copy':
            before[event['id']].add(event['source']['id'])
        elif event['kind'] == 'receipt':
            before[event['id']].add(event['copy'])
    return before


def histories(batch, initial, apply):
    """Yield the final state of every history consistent with the evidence.

    `apply(state, event)` returns the successor state, or None when the event's
    recorded outcome cannot occur in that state. Histories that reach the same
    state with the same events done are explored once.
    """
    by_id = {event['id']: event for event in events(batch)}
    before = precedence(batch)
    _require_acyclic(before)
    stack = [(frozenset(), initial)]
    seen = set()
    while stack:
        done, state = stack.pop()
        key = (done, state.fingerprint())
        if key in seen:
            continue
        seen.add(key)
        if len(done) == len(by_id):
            yield state
            continue
        for event_id in sorted(by_id):
            if event_id not in done and before[event_id] <= done:
                successor = apply(state, by_id[event_id])
                if successor is not None:
                    stack.append((done | {event_id}, successor))


def _require_acyclic(before):
    done = set()
    while len(done) < len(before):
        ready = {event_id for event_id, needed in before.items() if event_id not in done and needed <= done}
        if not ready:
            raise ValueError('ordering evidence is cyclic: %s' % ', '.join(sorted(set(before) - done)))
        done |= ready
